	private static final class ObjectProjection {

		private final Object[] source;
		private final int[] mapping;
		private Object[] target;
		private int size;

		private ObjectProjection(Object[] source) {
			this.source = source;
			mapping = new int[source.length];
			target = new Object[Math.min(Math.max(2, source.length), 32)];
		}

		private void remap(int[] objectIds) {
			for (int index = 0; index < objectIds.length; index++) {
				objectIds[index] = objectId(objectIds[index]);
			}
		}

		private int objectId(int sourceId) {
			if (sourceId == 0) {
				return 0;
			}
			int projected = mapping[sourceId];
			if (projected != 0) {
				return projected;
			}
			projected = ++size;
			if (projected == target.length) {
				target = Arrays.copyOf(target, target.length << 1);
			}
			mapping[sourceId] = projected;
			target[projected] = source[sourceId];
			return projected;
		}

		private Object[] values() {
			return Arrays.copyOf(target, size + 1);
		}
	}

